import React, { Fragment, useContext, useEffect, useState } from 'react' ;
import style from "./consumption.module.css"
import { Link } from 'react-router-dom';
import { UserContext } from '../../Context/UserContext.js';
import { QuantityContext } from '../../Context/QuantityContext.js';
import TimeAgo from '../TimeAgo/TimeAgo.jsx';
import ItemConsumption from '../ItemConsumption/ItemConsumption.jsx';

export default function Consumption() {
   const[countItem  , setCountItem] = useState(0) ;
   const[show , setShow] = useState("add") ;
   
   const{ getBranchQuantities , quantities , loading , getConsumption , consumption , checkConsumption} = useContext(QuantityContext) ;
   const{loggedUser} = useContext(UserContext) ;
   


   
   function handleShow (data){
      if(data === "get"){
         getConsumption("false") ;
      }
      setShow(data)
   }



   function handleCheckedConsumption(id){
      console.log(id);
      checkConsumption(id) ;
      
   }
   
   function handleSearch(search){
      if(search.length > 3){
         getBranchQuantities(search) ;
      }else{
         getBranchQuantities("") ;
      }
   }

   useEffect(() => {
      getBranchQuantities("") ;
   }, [loggedUser])

   return (
      <Fragment>
         <nav aria-label="breadcrumb" className='container my-3 bg-body-secondary'>
            <ol className="breadcrumb ">
               <li className="breadcrumb-item"><Link className="text-primary mx-2" to="/">Home</Link></li>
               <li className="breadcrumb-item active" aria-current="page">Consumption</li>
            </ol>
         </nav>

         
         <div className='d-flex justify-content-evenly my-5'>
            <button className='btn bg-main ' onClick={()=>{handleShow("add")}}>Add Consumption</button>
            <button className='btn bg-main ' onClick={()=>{handleShow("get")}}>All Consumption</button>
         </div>


         {show === "add"? 
               <div className='container my-5'>
                  <h1>Consumption</h1>

                  <div className=''>
                     <div className="mb-3">
                        <form >
                           <div className='position-relative'>
                              <input  type="search" onChange={(e) => handleSearch(e.target.value)}  className='form-control' id='search' placeholder='Search item more than 3 char'  name="search" />
                           </div>
                        </form>
                     </div>
                     {
                     loading?
                        <p className='fw-bold h4'>Loading...</p> 
                        :
                        <>
                           <h5>Please Add New Consumption :</h5>
                           <p><i class="fa-solid fa-mug-saucer mx-2"></i> Item Count  : {quantities.length || 0}</p>
                           {quantities.map((ele)=> <ItemConsumption key={ele._id} ele={ele}/>)}
                        </>
                     }

                  </div>
               </div>
            : 
               ""
         }




         {show === "get"? 
               <div className='container my-5'>
                  <h1>Consumption</h1>

                  <div className=''>
                     <div className="mb-3">
                        <form >
                           <div className='position-relative'>
                              <input  type="search" onChange={(e) => handleSearch(e.target.value)}  className='form-control' id='search' placeholder='Search item more than 3 char'  name="search" />
                           </div>
                        </form>
                     </div>
                     {
                     loading?
                        <p className='fw-bold h4'>Loading...</p> 
                        :
                        <>
                           <h5> All Consumption Branch <span className='text-primary'>{consumption[0]?.branch.name}</span> :</h5>
                           <p><i class="fa-solid fa-mug-saucer mx-2"></i> Item Count  : {consumption.length || 0}</p>
                           {consumption.map((ele)=>
                                 <div key={ele._id} className={`${style.quantityCart} container border border-2 rounded-2 my-3 p-0`}>
                                    <div className={`${style.title} row align-item-center mx-4 `}>
                                       <p className='col-10 text-success p-0 m-0'><i className="fa-solid fa-trophy me-2"></i>{ele.item?.name}</p>
                                       <p className='col-2 p-0 m-0'>
                                          <TimeAgo createdAt={ele.createdAt} showTimeOnly={true}/>
                                       </p>
                                    </div>

                                    <div>
                                       <table className="table order-table table-sm text-center">
                                          <thead>
                                             <tr>
                                                <th>Code</th>
                                                <th>Quantity</th>
                                                <th>Expired</th>
                                             </tr>
                                          </thead>
                                          <tbody>
                                                <tr>
                                                   <td>{ele.item.item_s_code}</td>
                                                   <td>{ele.quantity_consumed}</td>
                                                   <td>{new Date(ele.expired_date).toISOString().slice(0, 10)}</td>
                                                </tr>
                                          </tbody>
                                             <tfoot>
                                                <tr>
                                                   <td colspan="4"  className='m-0 p-0'>
                                                      <button className='btn btn-sm btn-success w-75 p-0 my-0' onClick={()=>{handleCheckedConsumption(ele.item._id)}}>Consumped Checked ✔</button>
                                                   </td>
                                                </tr>
                                             </tfoot>
                                       </table>
                                    </div>
                                 </div>
                              )
                           }
                        </>
                     }

                  </div>
               </div>
            : 
            ""
         }
      </Fragment>
   )
}
