import { createContext , useContext, useState } from "react";
import { UserContext } from "./UserContext.js";
import axios from "axios";
import { Navigate } from "react-router-dom";




export let QuantityContext = createContext();


export default function QuantityContextProvider(props){
   const {userToken , loggedUser} = useContext(UserContext) ;


   const [loading , setLoading] = useState(false) ;
   const [consumption , setConsumption] = useState([]) ;
   const [quantities , setQuantities] = useState([]) ;
   const [quantityExpired , setQuantityExpired] = useState([]) ;
   const [quantity , setQuantity] = useState({}) ;

   const header = {
      token:`${process.env.REACT_APP_BEARER_TOKEN} ${userToken || localStorage.getItem("token")}`
   }

   async function getBranchQuantities(search , flag){
      setLoading(true);
      await axios.get(`${process.env.REACT_APP_BASE_URL}/api/v1/quantity/quantitiesBranch?search=${search}&expired=${flag}`  ,  {headers:header} )
      .then(({data})=>{
         if(data.message === "success"){
            setQuantities(data.quantities) ;
            setLoading(false);
         }
      })
      .catch((error)=>{
         console.log(error.response.data.message);
         setQuantities([]) ;
         setLoading(false);
      })
   } ;

   
   async function getConsumption(consumed){
      setLoading(true);
      await axios.get(`${process.env.REACT_APP_BASE_URL}/api/v1/consumption/branchConsumption?consumed=${consumed}`  ,  {headers:header} )
      .then(({data})=>{
         if(data.message === "success"){
            setConsumption(data.consumption) ;
            setLoading(false);
         }
      })
      .catch((error)=>{
         console.log(error.response.data.message);
         setConsumption([]) ;
         setLoading(false);
      })
   } ;

   
   async function checkConsumption(itemId){
      setLoading(true);
      await axios.patch(`${process.env.REACT_APP_BASE_URL}/api/v1/consumption/${itemId}` , {} ,  {headers:header} )
      .then(({data})=>{
         if(data.message === "success"){
            getConsumption("false") ;
            setLoading(false);
         }
      })
      .catch((error)=>{
         console.log(error.response.data.message);
         setLoading(false);
      })
   } ;



   async function addConsumption(values){
      setLoading(true);
      await axios.post(`${process.env.REACT_APP_BASE_URL}/api/v1/consumption` , {...values}  ,  {headers:header} )
      .then(({data})=>{
         if(data.message === "success"){
            getBranchQuantities("") ;
            setLoading(false);
         }
      })
      .catch((error)=>{
         console.log(error.response.data.message);
         setLoading(false);
      })
   } ;



   async function getBranchQuantitiesExpired(search){
      setLoading(true);
      await axios.get(`${process.env.REACT_APP_BASE_URL}/api/v1/quantity/quantityExpired?search=${search}`  ,  {headers:header} )
      .then(({data})=>{
         if(data.message === "success"){
            setQuantityExpired(data.quantities) ;
            setLoading(false);
         }
      })
      .catch((error)=>{
         console.log(error.response.data.message);
         setQuantityExpired([]) ;
         setLoading(false);
      })
   } ;




   async function deleteQuantity(id){
      await axios.delete(`${process.env.REACT_APP_BASE_URL}/api/v1/quantity/${id}`  ,  {headers:header} )
      .then(({data})=>{
         if(data.message === "success"){
            getBranchQuantitiesExpired() ;
         }
      })
      .catch((error)=>{
         console.log(error.response.data.message);
      })
   } ;


   async function getSpecificQuantity(id){
      setLoading(true);
      await axios.get(`${process.env.REACT_APP_BASE_URL}/api/v1/quantity/${id}`  ,  {headers:header} )
      .then(({data})=>{
         if(data.message === "success"){
            setQuantity(data.Quantity)
            setLoading(false);
         }
      })
      .catch((error)=>{
         console.log(error.response.data.message);
         setLoading(false);
      })
   }
   return (
      <>
         <QuantityContext.Provider value={{
               getBranchQuantities , 
               getSpecificQuantity ,
               getBranchQuantitiesExpired ,
               deleteQuantity ,
               addConsumption , 
               getConsumption ,
               checkConsumption ,

               quantity , 
               setQuantity ,

               quantities ,
               setQuantities ,

               loading , 
               setLoading ,

               quantityExpired , 
               setQuantityExpired ,

               consumption ,  
               setConsumption ,
            }}>
            {props.children}
         </QuantityContext.Provider>
      </>
   )
}