import React, { Fragment, useContext, useEffect, useState } from 'react' ;
import style from "./inventory.module.css" ;
import { Link } from 'react-router-dom';
import { QuantityContext } from '../../Context/QuantityContext.js';
import TimeAgo from '../TimeAgo/TimeAgo.jsx';
import { UserContext } from '../../Context/UserContext.js';

export default function Inventory() {
   const{ getBranchQuantities , quantities , loading } = useContext(QuantityContext) ;
   const{loggedUser} = useContext(UserContext) ;
   const[show , setShow] = useState("all") ;

   function handleShow (data){
      if(data === "all"){
         getBranchQuantities("" , "false") ;
         setShow(data)
      }else if(data === "expired"){
         getBranchQuantities("" , "true") ;
         setShow(data)
      }
   }



   function handleSearch(search){
      if(search.length > 3){
         getBranchQuantities(search , "false") ;
      }else if(search.length === 0){
         getBranchQuantities("" , "false") ;
      }
   } ;



   useEffect(() => {
      getBranchQuantities("" , "false") ;
   }, [loggedUser])

   return (
      <Fragment>
         <nav aria-label="breadcrumb" className='container my-3 bg-body-secondary'>
            <ol className="breadcrumb ">
               <li className="breadcrumb-item"><Link className="text-primary mx-2" to="/">Home</Link></li>
               <li className="breadcrumb-item active" aria-current="page">Inventory</li>
            </ol>
         </nav>


                  <div className='d-flex justify-content-evenly my-5'>
                     <button className='btn bg-main ' onClick={()=>{handleShow("all")}}>All Items</button>
                     <button className='btn bg-main ' onClick={()=>{handleShow("expired")}}>Pre Expired</button>
                  </div>
         
         
                  {show === "all"? 
                     <div className='container my-5'>
                        <h1>Inventory</h1>

                        <div className=''>
                           <div className="mb-3">
                              <form >
                                 <div className='position-relative'>
                                    <input  type="search" onChange={(e) => handleSearch(e.target.value)}  className='form-control' id='search' placeholder='Search item more than 3 char'  name="search" />
                                 </div>
                              </form>
                           </div>
                           {
                           loading?
                              <p className='fw-bold h4'>Loading...</p> 
                              :
                              <>
                                 <h6>All Items Within  Branch <span className='text-primary'>{quantities[0]?.branch.name}</span></h6>
                                 <p><i class="fa-solid fa-mug-saucer mx-2"></i> Item Count  : {quantities.length || 0}</p>
                                 {
                                    quantities.map((ele)=>
                                       <div key={ele._id} className={`${style.quantityCart} container border border-2 rounded-2 my-3 p-0`}>
                                          <div className={`${style.title} row align-item-center mx-2`}>
                                             <p className='col-10 text-success p-0 m-0'><i class="fa-solid fa-trophy mx-2"></i>{ele.name}</p>
                                             <p className='col-2 p-0 m-0'>
                                                <TimeAgo createdAt={ele.createdAt} showTimeOnly={true}/>
                                             </p>
                                          </div>

                                          <div>
                                             <table className="table order-table table-sm text-center">

                                                <thead>
                                                   <tr>
                                                      <th>Code</th>
                                                      <th>Quantity</th>
                                                      <th>Delivery</th>
                                                      <th>Expired</th>
                                                   </tr>
                                                </thead>

                                                <tbody>
                                                      <tr key={ele.name}>
                                                         <td className='text-primary fw-bold'>{ele.item.item_s_code}</td>
                                                         <td>{ele.item_quantity}</td>
                                                         <td>{ele.delivery_number}</td>
                                                         <td className={ele.expired_date < Date.now()? "text-danger" : ""}>
                                                            {new Date(ele.expired_date).toISOString().slice(0, 10)}
                                                            {ele.expired_date < Date.now()? <span className='fw-bold mx-4'>Expired</span> : ""}
                                                         </td>
                                                      </tr>
                                                </tbody>
                                             </table>
                                          </div>
                                       </div>
                                    )
                                 }
                              </>
                           }

                        </div>
                     </div>
                     : 
                     ""
                  }
         
         
         
         
                  {show === "expired"? 
                     <div className='container my-5'>
                        <h1>Inventory</h1>

                        <div className=''>
                           {
                              loading?
                              <p className='fw-bold h4'>Loading...</p> 
                              :
                              <>
                                 <h6>Before Expired Items Through Monthly</h6>
                                 <p><i class="fa-solid fa-mug-saucer mx-2"></i> Item Count  : {quantities.length || 0}</p>
                                 {quantities.length? "" : <h4>Items Empty..!</h4>}

                                 {
                                    quantities.map((ele)=>
                                       <div key={ele._id} className={`${style.quantityCart} container border border-2 rounded-2 my-3 p-0`}>
                                          <div className={`${style.title} row align-item-center mx-2`}>
                                             <p className='col-10 text-success p-0 m-0'><i class="fa-solid fa-trophy mx-2"></i>{ele.name}</p>
                                             {/* <i class="fa-solid fa-bong"></i> */}
                                             {/* <i class="fa-solid fa-trophy"></i> */}
                                             <p className='col-2 p-0 m-0'>
                                                <TimeAgo createdAt={ele.createdAt} showTimeOnly={true}/>
                                             </p>
                                          </div>

                                          <div>
                                             <table className="table order-table table-sm text-center">
                                                <thead>
                                                   <tr>
                                                      <th>Code</th>
                                                      <th>Quantity</th>
                                                      <th>Delivery</th>
                                                      <th>Expired</th>
                                                   </tr>
                                                </thead>
                                                <tbody>
                                                      <tr key={ele.name}>
                                                         <td className='text-primary fw-bold'>{ele.item.item_s_code}</td>
                                                         <td>{ele.item_quantity}</td>
                                                         <td>{ele.delivery_number}</td>
                                                         <td className={ele.expired_date < Date.now()? "text-danger" : ""}>
                                                            {new Date(ele.expired_date).toISOString().slice(0, 10)}
                                                            {ele.expired_date < Date.now()? <span className='fw-bold mx-4'>Expired</span> : ""}
                                                         </td>                                                      </tr>
                                                </tbody>
                                             </table>
                                          </div>
                                       </div>
                                    )
                                 }
                              </>
                           }

                        </div>
                     </div>
                     : 
                     ""
                  }
      </Fragment>
   )
}
